mapper.select:
SELECT  FROM notification WHERE tenant_id=#{tenantId} AND recipient_user_id=#{recipientId}
AND state=#{state}
AND notification_kind=#{kind}
AND created_at >= #{from}
AND created_at <= #{to}

  AND (created_at >< #{cursorValue} OR (created_at=#{cursorValue} AND notification_id >< #{cursorId}))

ORDER BY created_at ASCDESC, notification_id ASCDESC LIMIT #{limit}
